## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/thyroidNoduleLogic.ts`

```typescript
/**
 * Thyroid Nodule Clinical Compass™ — Decision Support Logic
 * Based on:
 * - ATA Management Guidelines for Thyroid Nodules and Differentiated Thyroid Cancer 2023 Update (PMID: 39325028)
 * - ACR TI-RADS: Thyroid Imaging Reporting and Data System (PMID: 28372962)
 * - AACE/ACE/AME Medical Guidelines for Thyroid Nodule Management 2023 (PMID: 37116862)
 * - Bethesda System for Reporting Thyroid Cytopathology 2023 (PMID: 37154917)
 */

// ─── Input Types ─────────────────────────────────────────────────────────────

export type TIRADSCategory = "TR1" | "TR2" | "TR3" | "TR4" | "TR5";
export type BethesdaCategory = "I" | "II" | "III" | "IV" | "V" | "VI" | "not_done";
export type NoduleComposition = "cystic" | "spongiform" | "mixed" | "solid" | "predominantly_solid";
export type NoduleEchogenicity = "anechoic" | "hyperechoic" | "isoechoic" | "hypoechoic" | "markedly_hypoechoic";
export type NoduleShape = "wider_than_tall" | "taller_than_wide";
export type NoduleMargin = "smooth" | "ill_defined" | "lobulated" | "irregular" | "extrathyroidal";
export type EchogenicFoci = "none" | "large_comet_tail" | "macrocalcifications" | "peripheral_calcifications" | "punctate_echogenic_foci";

export interface ThyroidNoduleInput {
  // Nodule characteristics
  noduleSize: number; // cm (largest diameter)
  composition: NoduleComposition;
  echogenicity: NoduleEchogenicity;
  shape: NoduleShape;
  margin: NoduleMargin;
  echogenicFoci: EchogenicFoci;
  // TI-RADS (if already calculated)
  tiRadsCategory?: TIRADSCategory;
  tiRadsScore?: number;
  // Cytology
  bethesdaCategory: BethesdaCategory;
  // Clinical factors
  age: number;
  sex: "male" | "female";
  // Risk factors
  priorHeadNeckRT: boolean;
  familyHistoryThyroidCancer: boolean;
  familyHistoryMEN2: boolean;
  priorThyroidCancer: boolean;
  // Symptoms
  dysphagia: boolean;
  dysphonia: boolean;
  compressiveSymptoms: boolean;
  // Thyroid function
  tshLevel: number; // mIU/L (normal 0.4-4.0)
  // Lymphadenopathy
  suspiciousLymphadenopathy: boolean;
  // Molecular testing
  molecularTestResult?: "benign" | "suspicious" | "malignant" | "not_done";
  // Multinodular goiter
  multinodularGoiter: boolean;
  dominantNodule: boolean;
}

// ─── Output Types ─────────────────────────────────────────────────────────────

export type ThyroidDecision =
  | "no_biopsy_observe"
  | "biopsy_recommended"
  | "biopsy_optional"
  | "surgery_recommended"
  | "surgery_urgent"
  | "repeat_ultrasound"
  | "molecular_testing"
  | "thyroid_scan";

export interface ThyroidNoduleRecommendation {
  decision: ThyroidDecision;
  decisionLabel: string;
  // TI-RADS
  calculatedTIRADS: TIRADSCategory;
  tiRadsScore: number;
  malignancyRisk: string;
  // Biopsy details
  biopsyIndicated: boolean;
  biopsyThreshold: string;
  // Surgery details
  surgicalExtent?: string;
  surgicalRationale?: string;
  // Surveillance
  surveillanceInterval?: string;
  // Bethesda-based recommendation
  bethesdaRecommendation?: string;
  // Key warnings
  keyWarnings: string[];
  // Next steps
  nextSteps: string[];
  // Rationale
  rationale: string;
  evidenceLevel: "Strong" | "Moderate" | "Low" | "Expert consensus";
  guidelineSource: string;
}

// ─── TI-RADS Scoring ─────────────────────────────────────────────────────────

export function calculateTIRADS(input: ThyroidNoduleInput): { category: TIRADSCategory; score: number } {
  let score = 0;

  // Composition
  if (input.composition === "cystic") score += 0;
  else if (input.composition === "spongiform") score += 0;
  else if (input.composition === "mixed") score += 1;
  else if (input.composition === "solid" || input.composition === "predominantly_solid") score += 2;

  // Echogenicity
  if (input.echogenicity === "anechoic") score += 0;
  else if (input.echogenicity === "hyperechoic" || input.echogenicity === "isoechoic") score += 1;
  else if (input.echogenicity === "hypoechoic") score += 2;
  else if (input.echogenicity === "markedly_hypoechoic") score += 3;

  // Shape
  if (input.shape === "taller_than_wide") score += 3;

  // Margin
  if (input.margin === "smooth") score += 0;
  else if (input.margin === "ill_defined") score += 0;
  else if (input.margin === "lobulated" || input.margin === "irregular") score += 2;
  else if (input.margin === "extrathyroidal") score += 3;

  // Echogenic foci
  if (input.echogenicFoci === "none") score += 0;
  else if (input.echogenicFoci === "large_comet_tail") score += 0;
  else if (input.echogenicFoci === "macrocalcifications") score += 1;
  else if (input.echogenicFoci === "peripheral_calcifications") score += 2;
  else if (input.echogenicFoci === "punctate_echogenic_foci") score += 3;

  // Determine category
  let category: TIRADSCategory;
  if (score === 0) category = "TR1";
  else if (score === 2) category = "TR2";
  else if (score === 3) category = "TR3";
  else if (score >= 4 && score <= 6) category = "TR4";
  else category = "TR5";

  return { category, score };
}

export function getTIRADSMalignancyRisk(category: TIRADSCategory): string {
  switch (category) {
    case "TR1": return "Benign (0%)";
    case "TR2": return "Not suspicious (<2%)";
    case "TR3": return "Mildly suspicious (5%)";
    case "TR4": return "Moderately suspicious (5-20%)";
    case "TR5": return "Highly suspicious (>20%)";
  }
}

export function getBiopsyThreshold(category: TIRADSCategory): { size: number; recommendation: string } {
  switch (category) {
    case "TR1": return { size: 0, recommendation: "No biopsy — benign" };
    case "TR2": return { size: 0, recommendation: "No biopsy — not suspicious" };
    case "TR3": return { size: 2.5, recommendation: "FNA if ≥2.5 cm; follow if 1.5-2.5 cm" };
    case "TR4": return { size: 1.5, recommendation: "FNA if ≥1.5 cm; follow if 1.0-1.5 cm" };
    case "TR5": return { size: 1.0, recommendation: "FNA if ≥1.0 cm; follow if 0.5-1.0 cm" };
  }
}

// ─── Bethesda-Based Recommendation ───────────────────────────────────────────

export function getBethesdaRecommendation(input: ThyroidNoduleInput): string {
  const { bethesdaCategory, age, priorHeadNeckRT, familyHistoryThyroidCancer, noduleSize } = input;
  const highRisk = priorHeadNeckRT || familyHistoryThyroidCancer || age < 25 || age > 65;

  switch (bethesdaCategory) {
    case "I":
      return "Bethesda I (Non-diagnostic): Repeat FNA with ultrasound guidance — if repeatedly non-diagnostic and suspicious features, consider surgery";
    case "II":
      return "Bethesda II (Benign): No surgery — clinical follow-up and repeat ultrasound in 12-24 months";
    case "III":
      return `Bethesda III (AUS/FLUS): Malignancy risk 10-30%. Options: (1) Repeat FNA in 3-6 months, (2) Molecular testing (ThyroSeq v3, Afirma GSC), (3) Diagnostic lobectomy${highRisk ? " — HIGH RISK: molecular testing or lobectomy preferred" : ""}`;
    case "IV":
      return `Bethesda IV (FN/SFN): Malignancy risk 25-40%. Molecular testing (ThyroSeq v3, Afirma GSC) recommended — if suspicious/malignant: thyroid lobectomy or total thyroidectomy${noduleSize > 4 ? " — size >4 cm: total thyroidectomy preferred" : ""}`;
    case "V":
      return "Bethesda V (Suspicious for malignancy): Malignancy risk 60-75%. Thyroid lobectomy or total thyroidectomy recommended";
    case "VI":
      return "Bethesda VI (Malignant): Malignancy risk 97-99%. Total thyroidectomy (or lobectomy for low-risk papillary microcarcinoma)";
    case "not_done":
      return "FNA not performed — recommendation based on TI-RADS and clinical risk factors";
  }
}

// ─── Main Assessment Function ─────────────────────────────────────────────────

export function assessThyroidNodule(input: ThyroidNoduleInput): ThyroidNoduleRecommendation {
  const tiRads = input.tiRadsCategory
    ? { category: input.tiRadsCategory, score: input.tiRadsScore ?? 0 }
    : calculateTIRADS(input);
  const biopsyThreshold = getBiopsyThreshold(tiRads.category);
  const malignancyRisk = getTIRADSMalignancyRisk(tiRads.category);
  const bethesdaRec = getBethesdaRecommendation(input);
  const warnings: string[] = [];
  const nextSteps: string[] = [];

  // High-risk clinical features
  const highRiskClinical =
    input.priorHeadNeckRT ||
    input.familyHistoryMEN2 ||
    input.suspiciousLymphadenopathy ||
    input.dysphonia ||
    input.priorThyroidCancer;

  if (input.familyHistoryMEN2) {
    warnings.push("Family history of MEN2: RET proto-oncogene testing recommended — medullary thyroid cancer risk");
  }
  if (input.suspiciousLymphadenopathy) {
    warnings.push("Suspicious cervical lymphadenopathy: FNA of lymph node recommended regardless of nodule size");
  }
  if (input.dysphonia) {
    warnings.push("Dysphonia: evaluate for vocal cord paralysis — may indicate extrathyroidal extension");
  }
  if (input.tshLevel < 0.4) {
    warnings.push("Suppressed TSH: consider thyroid scan (I-123) — hyperfunctioning nodule has very low malignancy risk, FNA may not be needed");
  }
  if (input.tshLevel > 4.0) {
    warnings.push("Elevated TSH: associated with higher malignancy risk in thyroid nodules — lower threshold for FNA");
  }

  // ── Urgent: compressive symptoms or suspected malignancy ──
  if (input.compressiveSymptoms || (input.bethesdaCategory === "VI" && highRiskClinical)) {
    const surgicalExtent = input.bethesdaCategory === "VI"
      ? "Total thyroidectomy ± central neck dissection (if lymph node involvement)"
      : "Thyroid lobectomy or total thyroidectomy (depending on pathology)";
    return {
      decision: "surgery_recommended",
      decisionLabel: "Surgery Recommended",
      calculatedTIRADS: tiRads.category,
      tiRadsScore: tiRads.score,
      malignancyRisk,
      biopsyIndicated: input.bethesdaCategory === "not_done",
      biopsyThreshold: biopsyThreshold.recommendation,
      surgicalExtent,
      surgicalRationale: input.compressiveSymptoms
        ? "Compressive symptoms (dysphagia, stridor, SVC syndrome): surgical decompression indicated"
        : "Bethesda VI with high-risk features: total thyroidectomy recommended",
      bethesdaRecommendation: bethesdaRec,
      surveillanceInterval: undefined,
      keyWarnings: warnings,
      nextSteps: [
        "Endocrinology or thyroid surgery consultation",
        "Laryngoscopy if dysphonia present",
        "CT neck/chest if compressive symptoms or substernal extension",
        "Pre-operative calcium and PTH levels",
        "Discuss extent of surgery: lobectomy vs total thyroidectomy",
      ],
      rationale: "Surgery indicated for compressive symptoms or confirmed/highly suspicious malignancy.",
      evidenceLevel: "Strong",
      guidelineSource: "ATA 2023 (PMID: 39325028); AACE/ACE/AME 2023 (PMID: 37116862)",
    };
  }

  // ── Bethesda VI: Malignant ──
  if (input.bethesdaCategory === "VI") {
    return {
      decision: "surgery_recommended",
      decisionLabel: "Surgery Recommended (Bethesda VI — Malignant)",
      calculatedTIRADS: tiRads.category,
      tiRadsScore: tiRads.score,
      malignancyRisk: "97-99% (Bethesda VI)",
      biopsyIndicated: false,
      biopsyThreshold: "FNA already performed",
      surgicalExtent: input.noduleSize <= 1 && !highRiskClinical
        ? "Thyroid lobectomy (for low-risk papillary microcarcinoma ≤1 cm) — active surveillance is an option"
        : "Total thyroidectomy ± central neck dissection",
      surgicalRationale: "Bethesda VI: 97-99% malignancy risk. Total thyroidectomy for tumors >1 cm or high-risk features.",
      bethesdaRecommendation: bethesdaRec,
      keyWarnings: [
        ...warnings,
        input.noduleSize <= 1 ? "Papillary microcarcinoma (≤1 cm): active surveillance is an ATA 2023 option for low-risk patients — discuss with patient" : "",
      ].filter(Boolean),
      nextSteps: [
        "Endocrine surgery consultation",
        "Neck ultrasound to evaluate lymph nodes",
        "Discuss extent of surgery: lobectomy vs total thyroidectomy",
        "RAI eligibility discussion if total thyroidectomy planned",
        "Pre-operative calcium and PTH",
      ],
      rationale: "Bethesda VI: surgery is recommended. For low-risk papillary microcarcinoma ≤1 cm, active surveillance is an option per ATA 2023.",
      evidenceLevel: "Strong",
      guidelineSource: "ATA 2023 (PMID: 39325028)",
    };
  }

  // ── Bethesda V: Suspicious for malignancy ──
  if (input.bethesdaCategory === "V") {
    return {
      decision: "surgery_recommended",
      decisionLabel: "Surgery Recommended (Bethesda V — Suspicious)",
      calculatedTIRADS: tiRads.category,
      tiRadsScore: tiRads.score,
      malignancyRisk: "60-75% (Bethesda V)",
      biopsyIndicated: false,
      biopsyThreshold: "FNA already performed",
      surgicalExtent: "Thyroid lobectomy or total thyroidectomy — based on nodule size, contralateral disease, and patient preference",
      surgicalRationale: "Bethesda V: 60-75% malignancy risk. Surgical excision recommended.",
      bethesdaRecommendation: bethesdaRec,
      keyWarnings: warnings,
      nextSteps: [
        "Endocrine surgery consultation",
        "Molecular testing (ThyroSeq v3 or Afirma GSC) may help guide extent of surgery",
        "Neck ultrasound for lymph node evaluation",
        "Discuss lobectomy vs total thyroidectomy",
      ],
      rationale: "Bethesda V: surgery recommended. Molecular testing may help differentiate malignant subtypes and guide surgical extent.",
      evidenceLevel: "Strong",
      guidelineSource: "ATA 2023 (PMID: 39325028); Bethesda System 2023 (PMID: 37154917)",
    };
  }

  // ── Bethesda IV: Follicular neoplasm ──
  if (input.bethesdaCategory === "IV") {
    return {
      decision: "molecular_testing",
      decisionLabel: "Molecular Testing Recommended (Bethesda IV)",
      calculatedTIRADS: tiRads.category,
      tiRadsScore: tiRads.score,
      malignancyRisk: "25-40% (Bethesda IV)",
      biopsyIndicated: false,
      biopsyThreshold: "FNA already performed",
      surgicalExtent: "Thyroid lobectomy (if molecular testing suspicious/malignant) or total thyroidectomy (if >4 cm or bilateral disease)",
      bethesdaRecommendation: bethesdaRec,
      keyWarnings: [
        ...warnings,
        "Bethesda IV: FNA cannot distinguish follicular adenoma from follicular carcinoma — molecular testing or surgery required",
      ],
      nextSteps: [
        "Molecular testing: ThyroSeq v3 or Afirma GSC — if benign result, follow with ultrasound; if suspicious/malignant, proceed to surgery",
        "If molecular testing not available: diagnostic thyroid lobectomy",
        "Endocrine surgery consultation",
        "Neck ultrasound for lymph node evaluation",
      ],
      rationale: "Bethesda IV: molecular testing (ThyroSeq v3 or Afirma GSC) is recommended to risk-stratify and guide surgical decision. If benign result: follow with ultrasound. If suspicious/malignant: lobectomy or total thyroidectomy.",
      evidenceLevel: "Strong",
      guidelineSource: "ATA 2023 (PMID: 39325028); Bethesda System 2023 (PMID: 37154917)",
    };
  }

  // ── Bethesda III: AUS/FLUS ──
  if (input.bethesdaCategory === "III") {
    return {
      decision: "molecular_testing",
      decisionLabel: "Molecular Testing or Repeat FNA (Bethesda III)",
      calculatedTIRADS: tiRads.category,
      tiRadsScore: tiRads.score,
      malignancyRisk: "10-30% (Bethesda III)",
      biopsyIndicated: false,
      biopsyThreshold: "FNA already performed",
      bethesdaRecommendation: bethesdaRec,
      surveillanceInterval: "Repeat FNA in 3-6 months if molecular testing not available",
      keyWarnings: warnings,
      nextSteps: [
        "Molecular testing: ThyroSeq v3 or Afirma GSC (preferred over repeat FNA per ATA 2023)",
        "If molecular testing benign: follow with ultrasound in 12-24 months",
        "If molecular testing suspicious/malignant: proceed to surgery",
        "Endocrinology consultation",
      ],
      rationale: "Bethesda III: molecular testing is preferred over repeat FNA per ATA 2023. ThyroSeq v3 has 94% sensitivity and 82% specificity for malignancy.",
      evidenceLevel: "Moderate",
      guidelineSource: "ATA 2023 (PMID: 39325028); Bethesda System 2023 (PMID: 37154917)",
    };
  }

  // ── Bethesda II: Benign ──
  if (input.bethesdaCategory === "II") {
    return {
      decision: "repeat_ultrasound",
      decisionLabel: "Surveillance Ultrasound (Bethesda II — Benign)",
      calculatedTIRADS: tiRads.category,
      tiRadsScore: tiRads.score,
      malignancyRisk: "0-3% (Bethesda II)",
      biopsyIndicated: false,
      biopsyThreshold: "FNA already performed — benign result",
      bethesdaRecommendation: bethesdaRec,
      surveillanceInterval: "Repeat ultrasound in 12-24 months; if stable × 2 years, extend to 3-5 years",
      keyWarnings: [
        ...warnings,
        "Bethesda II false-negative rate: 0-3% — repeat FNA if nodule grows >20% or new suspicious features develop",
      ],
      nextSteps: [
        "Repeat ultrasound in 12-24 months",
        "If nodule grows >20% in 2 dimensions: repeat FNA",
        "Endocrinology follow-up",
      ],
      rationale: "Bethesda II: benign cytology. Surveillance ultrasound recommended. False-negative rate 0-3%.",
      evidenceLevel: "Strong",
      guidelineSource: "ATA 2023 (PMID: 39325028)",
    };
  }

  // ── No FNA yet — TI-RADS based recommendation ──
  const biopsyNeeded = biopsyThreshold.size > 0 && input.noduleSize >= biopsyThreshold.size;
  const biopsyOptional = biopsyThreshold.size > 0 && input.noduleSize >= biopsyThreshold.size * 0.6 && input.noduleSize < biopsyThreshold.size;

  if (tiRads.category === "TR1" || tiRads.category === "TR2") {
    return {
      decision: "no_biopsy_observe",
      decisionLabel: "No Biopsy — Observation Only",
      calculatedTIRADS: tiRads.category,
      tiRadsScore: tiRads.score,
      malignancyRisk,
      biopsyIndicated: false,
      biopsyThreshold: biopsyThreshold.recommendation,
      bethesdaRecommendation: bethesdaRec,
      surveillanceInterval: tiRads.category === "TR1" ? "No follow-up needed" : "No follow-up needed unless clinical change",
      keyWarnings: warnings,
      nextSteps: [
        "No FNA required",
        tiRads.category === "TR2" ? "No routine follow-up ultrasound needed" : "No further workup needed",
        "Return if new symptoms develop (dysphagia, dysphonia, rapid growth)",
      ],
      rationale: `TI-RADS ${tiRads.category}: benign/not suspicious. FNA not indicated. Malignancy risk ${malignancyRisk}.`,
      evidenceLevel: "Strong",
      guidelineSource: "ACR TI-RADS (PMID: 28372962); ATA 2023 (PMID: 39325028)",
    };
  }

  if (biopsyNeeded || highRiskClinical) {
    nextSteps.push("Ultrasound-guided FNA biopsy");
    nextSteps.push("Endocrinology consultation");
    if (input.tshLevel < 0.4) {
      nextSteps.push("Thyroid scan (I-123) before FNA — hyperfunctioning nodule has very low malignancy risk");
    }
    return {
      decision: "biopsy_recommended",
      decisionLabel: `FNA Biopsy Recommended (TI-RADS ${tiRads.category}, size ${input.noduleSize} cm)`,
      calculatedTIRADS: tiRads.category,
      tiRadsScore: tiRads.score,
      malignancyRisk,
      biopsyIndicated: true,
      biopsyThreshold: biopsyThreshold.recommendation,
      bethesdaRecommendation: bethesdaRec,
      keyWarnings: warnings,
      nextSteps,
      rationale: `TI-RADS ${tiRads.category} nodule ≥${biopsyThreshold.size} cm: FNA recommended per ACR TI-RADS and ATA 2023. Malignancy risk ${malignancyRisk}.`,
      evidenceLevel: "Strong",
      guidelineSource: "ACR TI-RADS (PMID: 28372962); ATA 2023 (PMID: 39325028)",
    };
  }

  // Surveillance only
  const followUpInterval =
    tiRads.category === "TR3" ? "1-2 years" :
    tiRads.category === "TR4" ? "1 year" :
    tiRads.category === "TR5" ? "6-12 months" : "1-2 years";

  return {
    decision: biopsyOptional ? "biopsy_optional" : "repeat_ultrasound",
    decisionLabel: biopsyOptional
      ? `FNA Optional (TI-RADS ${tiRads.category}, size ${input.noduleSize} cm — below threshold)`
      : `Surveillance Ultrasound (TI-RADS ${tiRads.category})`,
    calculatedTIRADS: tiRads.category,
    tiRadsScore: tiRads.score,
    malignancyRisk,
    biopsyIndicated: biopsyOptional,
    biopsyThreshold: biopsyThreshold.recommendation,
    bethesdaRecommendation: bethesdaRec,
    surveillanceInterval: `Repeat ultrasound in ${followUpInterval}`,
    keyWarnings: warnings,
    nextSteps: [
      biopsyOptional ? "FNA may be considered — discuss with patient" : `Repeat ultrasound in ${followUpInterval}`,
      "If nodule grows >20% in 2 dimensions: FNA recommended",
      "Endocrinology consultation if TSH abnormal",
    ],
    rationale: `TI-RADS ${tiRads.category} nodule below FNA threshold (${biopsyThreshold.recommendation}). Surveillance ultrasound recommended.`,
    evidenceLevel: "Strong",
    guidelineSource: "ACR TI-RADS (PMID: 28372962); ATA 2023 (PMID: 39325028)",
  };
}

// ─── Utility Functions ─────────────────────────────────────────────────────────

export function getDecisionColor(decision: ThyroidDecision): string {
  switch (decision) {
    case "no_biopsy_observe": return "bg-emerald-900/40 border-emerald-600 text-emerald-300";
    case "repeat_ultrasound": return "bg-blue-900/40 border-blue-600 text-blue-300";
    case "biopsy_optional": return "bg-yellow-900/40 border-yellow-600 text-yellow-300";
    case "biopsy_recommended": return "bg-orange-900/40 border-orange-600 text-orange-300";
    case "molecular_testing": return "bg-violet-900/40 border-violet-600 text-violet-300";
    case "surgery_recommended": return "bg-red-900/40 border-red-600 text-red-300";
    case "surgery_urgent": return "bg-red-900/60 border-red-500 text-red-200";
    case "thyroid_scan": return "bg-teal-900/40 border-teal-600 text-teal-300";
    default: return "bg-slate-800/50 border-slate-600 text-slate-400";
  }
}

export function getTIRADSColor(category: TIRADSCategory): string {
  switch (category) {
    case "TR1": return "text-emerald-400";
    case "TR2": return "text-green-400";
    case "TR3": return "text-yellow-400";
    case "TR4": return "text-orange-400";
    case "TR5": return "text-red-400";
  }
}
